% Fast-minus-slow differentiation of (m_d - m_I)
m_d2_encoded = (m_F2_d + m_S2_I) - ...
               (m_S2_d + m_F2_I);

% Desired one-sided output: numerical reference only
m_gate2_target = max(m_d2_encoded, 0);

% Ideal counter-enable signal: numerical reference only
gate2_ref = double(m_d2_encoded > 0);

% Count elapsed time while enabled, then hold the result
time_count_ref = [0; cumsum(diff(t).*gate2_ref(1:end-1))];

figure; %[output:11d839bc]
